-- 17: POST-FLIGHT for the eight tranche-2 website migrations 20261020100000 .. 20261020170000. Read-only. Every row should say ok = true.
with
fn as (select p.oid, p.proname, p.prosecdef, p.proconfig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = any(array['venue_payment_rules','save_venue_payment_rules','desk_booking_guests','desk_booking_activity','list_org_event_states','event_door_allowed','organizer_event_door_status','venue_door_permissions','set_organizer_door_staff','venue_event_door_staff','revoke_event_door_access','desk_walkin_options','desk_create_walkin','desk_may_add_bottles','desk_bottle_menu','desk_booking_deliveries','desk_deliver_part','door_admit_group','door_admission_counts','door_guest_admissions']::text[])),
app as (select * from fn where proname <> 'event_door_allowed'),
inv as (select p.oid, p.prosrc, p.prosecdef, p.proconfig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.proname = 'invite_member'
           and pg_get_function_identity_arguments(p.oid) = 'p_org uuid, p_email text, p_role text, p_venue uuid, p_event uuid, p_shift uuid, p_access_start timestamp with time zone, p_access_end timestamp with time zone, p_valid_for interval')
select * from (
  select 1 as n, 'the 20 new functions exist' as check_name, (select count(distinct proname) from fn)::text as actual, '20' as expected, (select count(distinct proname) from fn) = 20 as ok
  union all select 2, 'none of them is callable by anonymous visitors', (select count(*) from fn where has_function_privilege('anon', oid, 'execute'))::text, '0', (select count(*) from fn where has_function_privilege('anon', oid, 'execute')) = 0
  union all select 3, 'the 19 app-facing functions are callable by signed-in people', (select count(*) from app where has_function_privilege('authenticated', oid, 'execute'))::text, '19', (select count(*) from app where has_function_privilege('authenticated', oid, 'execute')) = 19
  union all select 4, 'the internal rule event_door_allowed is NOT callable by signed-in people', (select count(*) from fn where proname = 'event_door_allowed' and has_function_privilege('authenticated', oid, 'execute'))::text, '0', (select count(*) from fn where proname = 'event_door_allowed' and has_function_privilege('authenticated', oid, 'execute')) = 0
  union all select 5, 'every new function runs with its owner''s rights and a fixed search_path', (select count(*) from fn where not prosecdef or proconfig is null or not exists (select 1 from unnest(proconfig) c where c like 'search_path=%'))::text, '0',
         (select count(*) from fn where not prosecdef or proconfig is null or not exists (select 1 from unnest(proconfig) c where c like 'search_path=%')) = 0
  union all select 6, 'site_agreements.organizer_door_staff exists, is boolean, not null, default false', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'site_agreements' and column_name = 'organizer_door_staff' and data_type = 'boolean' and is_nullable = 'NO' and column_default = 'false')::text, '1',
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'site_agreements' and column_name = 'organizer_door_staff' and data_type = 'boolean' and is_nullable = 'NO' and column_default = 'false') = 1
  union all select 7, 'invite_member now applies the organizer door staff rule', (select count(*) from inv where position('event_door_allowed' in prosrc) > 0)::text, '1', (select count(*) from inv where position('event_door_allowed' in prosrc) > 0) = 1
  union all select 8, 'invite_member is still owner-rights with a fixed search_path, callable by signed-in people and not by visitors',
         (select count(*) from inv where prosecdef and proconfig is not null and exists (select 1 from unnest(proconfig) c where c like 'search_path=%') and has_function_privilege('authenticated', oid, 'execute') and not has_function_privilege('anon', oid, 'execute'))::text, '1',
         (select count(*) from inv where prosecdef and proconfig is not null and exists (select 1 from unnest(proconfig) c where c like 'search_path=%') and has_function_privilege('authenticated', oid, 'execute') and not has_function_privilege('anon', oid, 'execute')) = 1
  union all select 9, 'site_table_booking_bottles.delivered_quantity exists, is an integer, not null, default 0', (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'delivered_quantity' and data_type = 'integer' and is_nullable = 'NO' and column_default = '0')::text, '1',
         (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'site_table_booking_bottles' and column_name = 'delivered_quantity' and data_type = 'integer' and is_nullable = 'NO' and column_default = '0') = 1
  union all select 10, 'no bottle line has a delivered count above its quantity (the function never allows it)', (select count(*) from public.site_table_booking_bottles l where coalesce((to_jsonb(l) ->> 'delivered_quantity')::int, 0) > l.quantity)::text, '0',
         (select count(*) from public.site_table_booking_bottles l where coalesce((to_jsonb(l) ->> 'delivered_quantity')::int, 0) > l.quantity) = 0
  union all select 11, 'site_order_admissions exists, has row level security, and is closed to signed-in people and visitors', (select count(*) from pg_class c where c.oid = to_regclass('public.site_order_admissions') and c.relrowsecurity and not has_table_privilege('authenticated', c.oid, 'select,insert,update,delete') and not has_table_privilege('anon', c.oid, 'select,insert,update,delete'))::text, '1',
         (select count(*) from pg_class c where c.oid = to_regclass('public.site_order_admissions') and c.relrowsecurity and not has_table_privilege('authenticated', c.oid, 'select') and not has_table_privilege('authenticated', c.oid, 'insert') and not has_table_privilege('authenticated', c.oid, 'update') and not has_table_privilege('authenticated', c.oid, 'delete') and not has_table_privilege('anon', c.oid, 'select') and not has_table_privilege('anon', c.oid, 'insert')) = 1
  union all select 12, 'no club has been given a door staff permission by the migration (only a club''s own switch may set it)', (select count(*) from public.site_agreements a where coalesce((to_jsonb(a) ->> 'organizer_door_staff')::boolean, false))::text, 'any (0 right after applying)', true
) x order by n;
